"""Append bounded comparison and geometry/interface evidence; no manuscript edits."""
import json
from pathlib import Path
ROOT=Path(r'D:\Users\Ben Bolen\NeuroCampaign_20261031')

def section(path,title,body):
 old=path.read_text(encoding='utf-8');marker='## '+title
 if marker in old:
  start=old.index(marker);end=old.find('\n## ',start+len(marker));old=old[:start]+(old[end:] if end>=0 else '')
 path.write_text(old.rstrip()+'\n\n'+marker+'\n\n'+body.rstrip()+'\n',encoding='utf-8')

def main():
 gait=ROOT/'gait_bpa';cad=ROOT/'cad_bpa';data=json.loads((gait/'OTHER_FAMILY_STANDING_CHECKPOINT.json').read_text());body='Both remaining families received exactly the same three shared bilateral standing variables, bounds, seed, initial candidates, corrected pose, biological force model, baseline rig, objective gates, 12-trial limit, and 600 s ceiling as syn6. Two completed baseline/PF-ablation observations were reused per family. No broad insensitive-gain sweep or Optuna database migration was performed. Each best candidate was repeated from its exact JSON in a fresh process.\n\n| Family | Gate | Fresh exact | Tilt (deg) | Sway (mm) | Foot load (BW) | Upward rig (%BW) |\n| --- | --- | --- | ---: | ---: | ---: | ---: |\n'
 for row in data['families']:
  a=row['assessment'];body+=f"| {row['family']} | {a['accepted']} | {row['bit_exact']} | {a['tilt_deg']:.3f} | {a['sway_m']*1000:.2f} | {a['normal_force_bw']:.4f} | {row['upward_rig_bw']*100:.4f} |\n"
 body+='\nBoth selected the tested PF→MN=0, aggregate IBEXC→MN=0, and standing-bias scale=0.8333333333333334 point. This disables those two connection classes functionally while preserving the remaining source neurons/reflex circuitry; it is a stage-specific standing configuration, not a source walking result. In particular, w2lvar remains a nonpass: the harness carries about 71% BW and the foot-load and sway gates fail. Small torso tilt alone is not successful standing. Neither candidate is promoted to gait or a full curriculum. Visual penetration and all signed apparatus forces remain in the raw/checkpoint files.\n\nOTHER_FAMILY_CURRENT_AUDIT.json attributes late winner currents using the actual rebuilt graph and saved voltages. The s3k winner retains positive direct II feedback (mean +0.516 nA/MN). The w2lvar winner retains antagonist IIIN inhibition (−1.878 nA/MN) versus IIX excitation (+0.859 nA/MN), after the PF and aggregate-Ib branches were turned off. Its per-target IIIN fan-in is listed explicitly. This is code/state evidence, not a claim that every author used that physiology or that a single inhibitory arrow has that net effect. Any normalization intervention must be opt-in and separately labeled.\n'
 transfer=json.loads((gait/'other_family_pressure/S3K_PREPARED_TRANSFER.json').read_text());body+='\nThe accepted s3k candidate was then tested without neural retuning under the same 0.6 s pinned preparation policy. Biological standing passes, but substitution of the existing syn6-sized virtual pressure actuators hits the unchanged right-pectineus supported-sleeve domain guard (0.885 micrometre excess at 22.55 kPa). No resizing or guard relaxation was applied, and no fresh BPA pass is claimed. w2lvar pressure transfer remains gated out because its biological standing fails. Exact cases: other_family_pressure/S3K_PREPARED_TRANSFER.json.\n'
 section(gait/'EXPERIMENT_RECORD.md','Equal-budget s3k and w2lvar standing calibration',body)
 proposal=json.loads((cad/'mount_subset/PAIRED_REMOTE_SLEEVE_MOUNT_PROPOSAL.json').read_text());parity=json.loads((cad/'CAD_MOVING_FORCE_PARITY.json').read_text());body='The complete moving-route force bridge is implemented opt-in in cad_moving_force.py. All native gains/biases must be disabled explicitly before the external positive-tension force is applied once as −J_length.T T. This preserves the caller\'s other force contributions and avoids mixing native reference tensions with BPAs or applying moving-site correction twice. It does not alter neurons or install a torque allocator.\n\nActual 54-route AH001 tests at three saved poses match finite-difference geometry derivatives within '+str(max(r['full_jacobian_error_m_per_rad_or_m'] for r in parity['cases']))+' m per generalized coordinate; mechanical power matches within3.4e−16 W. Using only fixed-site native derivatives would miss up to0.04951 m/rad in these cases. The test uses prescribed synthetic 10–100 N tensions, not calibrated BPA output or standing. See CAD_MOVING_FORCE_PARITY.json.\n\nEighteen direct historical single-BPA sleeve placements were screened. None simultaneously satisfies current length budget, proximal straight-span packaging, and conservative CAD-envelope separation. Historical dimensions cannot simply be transplanted onto the present route drawings.\n\nA separate bounded remote-sleeve proposal uses actual thigh mesh bounds and the 401-pose original cable-route excursions. The four candidate sleeves below pass conservative mesh/nonmesh-envelope separation at17saved whole-body poses. Paired sleeve dimensions are tied to the larger bilateral route excursion; a10% geometric contraction margin is retained below the declared25% maximum. Their cables, Bowden housing, fittings, brackets, and attachment loads remain unverified. No claim of a fully mountable or calibrated whole actuator is made.\n\n| Existing route | Shared sleeve rest (m) | Straight mounting span (m) | Additional external offset (m) |\n| --- | ---: | ---: | ---: |\n'
 for row in proposal['routes']:body+=f"| {row['name']} | {row['derived_sleeve_rest_m']:.5f} | {row['straight_mount_span_m']:.5f} | {row['selected_mount']['additional_surface_offset_m']:.3f} |\n"
 body+='\nThe proposed Bowden outlet is fixed at the existing same-thigh route eye; its ideal constant housing/remote-span length does not change the original route Jacobian. Exact housing length, bend routing/radius, friction, effective series stiffness, pressure response, and component masses remain unassigned. The38.5 mm inflated-diameter envelope comes from the historical Routing27 design assumption, with an explicitly assumed2 mm additional clearance. No human fiber length or MIF was substituted for these missing hardware values. The initial asymmetric-sleeve proposal is retained as intermediate geometry; PAIRED_REMOTE_SLEEVE_MOUNT_PROPOSAL.json is the adopted paired screen.\n\nExisting naming discrepancy found and preserved: active vas_med_r/l is assigned master actuator ID11 labeled Vastus Intermedius in robotbody_routes.json. The proposal follows the actual active vas_med paths; it does not silently relabel them or claim anatomical identity. Sleeve clearances are geometric proposal evidence, not neural standing, calibrated mounted hardware, complete cable packaging, or swept continuous-motion validation.\n'
 section(cad/'EXPERIMENT_RECORD.md','Moving-route parity and bounded sleeve mounting proposal',body)
 print('Updated separate family and CAD records')

if __name__=='__main__':main()
